import sys

mods = {}
for m in ("pandas", "openpyxl", "xlrd", "zipfile", "xml.etree.ElementTree"):
    try:
        __import__(m)
        mods[m] = "ok"
    except Exception as e:
        mods[m] = f"missing: {e}"
print(mods)

try:
    import pandas as pd
    xl = pd.ExcelFile("sales_data.xlsx")
    print("sheets:", xl.sheet_names)
    for s in xl.sheet_names:
        df = pd.read_excel("sales_data.xlsx", sheet_name=s, header=None)
        print(f"--- {s} shape={df.shape}")
        print(df.head(15).to_string())
except Exception as e:
    print("pandas path failed:", repr(e))

